def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    hs = [i for i, row in enumerate(grid) if all(x == 8 for x in row)]
    vs = [j for j in range(w) if all(grid[i][j] == 8 for i in range(h))]
    rs, re = [0] + [x+1 for x in hs], hs + [h]
    cs, ce = [0] + [x+1 for x in vs], vs + [w]
    for bi in range(len(hs)):
        a, b, c, d = rs[bi], re[bi], rs[bi+1], re[bi+1]
        for j0, j1 in zip(cs, ce):
            for i in range(a, b):
                for j in range(j0, j1):
                    v = grid[i][j]
                    ii = c + b - 1 - i
                    if v not in (0, 8) and ii < d and out[ii][j] == 0:
                        out[ii][j] = v
    return out
